class DataStream {
    private int val;
    private int k;
    private int count;

    public DataStream(int value, int k) {
        this.val = value;
        this.k = k;
        this.count = 0;
    }

    public boolean consec(int num) {
        if (num == val) count++;
        else count = 0;
        return count >= k;
    }
}

var DataStream = function(value, k) {
    this.val = value;
    this.k = k;
    this.count = 0;
};

DataStream.prototype.consec = function(num) {
    if (num === this.val) this.count++;
    else this.count = 0;
    return this.count >= this.k;
};
